text:
{
  "questions": [
    {
      "n": 1,
      "start": "Stimmt es, dass die Spitäler Schaffhausen",
      "end": "um ihn an eine Drittfirma zu vergeben?"
    },
    {
      "n": 2,
      "start": "Werden für den externalisierten Betrieb tiefere oder höhere Produkt- resp.",
      "end": "wie plant der Spitalrat das betroffene Personal zu schützen?"
    },
    {
      "n": 3,
      "start": "Aufgrund welcher gesetzlichen Grundlage sieht sich der Spitalrat resp.",
      "end": "in Eigenregie zu fällen und in die Wege zu leiten?"
    },
    {
      "n": 4,
      "start": "Art.11 Abs.1 lit. d des Spitalgesetzes (RSS 813.100) sagt ja eigentlich, dass",
      "end": "in absehbarer Zeit eine entsprechende Vorlage zuhanden des Kantonsrates verabschieden?"
    },
    {
      "n": 5,
      "start": "Wenn nein: Handelt es sich bei der geplanten Auslagerung der AEMP nicht um einen Fall",
      "end": "Warum nicht?"
    },
    {
      "n": 6,
      "start": "Unter welche Bestimmung fallen Auslagerungen von Betriebsbereichen, die nur in unerheblichem Masse",
      "end": "in die Kompetenz des Kantonsrats (Art. 10 Abs. 1 lit. b) oder in die Kompetenz des Regierungsrats (Art. 10 lit. a oder lit. c)?"
    },
    {
      "n": 7,
      "start": "§3 Abs. 2 zweiter Satz der Spitalverordnung (RSS 813.101) erlaubt für die Leistungserbringung der Listenspitäler die Untervergabe von Supportleistungen an Dritte sowie die Kooperation mit anderen Spitälern.",
      "end": "Wie fügt sich diese Auslegung in die Gesetzeshierarchie?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Die SSH haben im letzten Jahr eine betriebswirtschaftliche Prüfung verschiedener Modelle für",
      "end": "den Spitalrat hat daraufhin entschieden, von der Auslagerung an einen Drittanbieter abzusehen."
    },
    {
      "n": 2,
      "start": "Bei einer Auslagerung seien demnach tiefere Kosten zu erwarten, da z. B.",
      "end": "so fand in der nachfolgenden Analyse auch die übrigen Aspekte verstärkt Berücksichtigung."
    },
    {
      "n": 3,
      "start": "Der Betrieb der AEMP ist der sogenannten Bedarfsverwaltung zuzuordnen.",
      "end": "Dementsprechend wäre der Spitalrat als oberstes Führungsorgan der SSH (gestützt auf Art. 14 Abs. 1 und 3 Spitalgesetz) für die Auslagerung der AEMP an ein Privatunternehmen zuständig."
    },
    {
      "n": 4,
      "start": "Nein, dies ist nicht vorgesehen.",
      "end": "Andererseits wäre eine Vorlage an den Kantonsrat im vorliegenden Fall ohnehin nicht erforderlich, da es sich nicht um eine bewilligungspflichtige Tatsache im Sinne von Artikel 11 Absatz 1 Buchstabe d Spitalgesetz handelt."
    },
    {
      "n": 5,
      "start": "Es handelt sich nicht um einen solchen Fall; vgl. hierzu die Antworten zu den Fragen 3 und 4",
      "end": "vorstehend."
    },
    {
      "n": 6,
      "start": "Die Auslagerung von Betriebsbereichen, die nur in unerheblichem Ausmass Dienstleistungen zugunsten Dritter erbringen,",
      "end": "liegt nicht in der Kompetenz des Kantonsrates oder des Regierungsrates, sondern in jener des Spitalrates als oberstes Führungsorgan der SSH (gestützt auf Art. 14 Abs. 1 und 3 Spitalgesetz)."
    },
    {
      "n": 7,
      "start": "§ 3 Absatz 2 zweiter Satz der Spitalverordnung erlaubt ausdrücklich, unterstützende Dienstleistungen, wie sie die AEMP erbringt, an Dritte zu vergeben.",
      "end": "Dies steht nicht im Widerspruch zum Spitalgesetz, vielmehr ist die Untervergabe von Supportleistungen an Dritte in diesem Sinne von den in Artikel 10 Absatz 1 Spitalgesetz vorgesehenen Beteiligungen und Auslagerungen abzugrenzen."
    }
  ],
  "submitter": "Patrick Portmann",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "An dieser Stelle sei festgehalten, dass die Spitäler Schaffhausen (SSH) infolge einer erneuten, ganzheitlichen Analyse entschieden haben, die Aufbereitungseinheit für Medizinprodukte (AEMP) – entgegen der ursprünglichen Planung – nicht auszulagern.",
    "end": "Der Spitalrat hat daraufhin entschieden, von der Auslagerung an einen Drittanbieter abzusehen."
  }
}
